<?php
require_once __DIR__.'/../../includes/functions.php';require_admin();$notice='';$error='';
$fields=['business_address'=>'Business address','business_phone'=>'Business phone','business_email'=>'Business email','business_hours'=>'Business hours','bank_details'=>'Bank transfer instructions','facebook_url'=>'Facebook URL','instagram_url'=>'Instagram URL','tiktok_url'=>'TikTok URL','whatsapp_url'=>'WhatsApp URL','verified_customers'=>'Verified happy customers (optional)','completed_projects'=>'Verified completed projects (optional)','years_experience'=>'Verified years of experience (optional)'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$pdo=db();$stmt=$pdo->prepare('INSERT INTO website_settings (setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($fields as $key=>$label){$value=trim((string)($_POST[$key]??''));if($key==='business_email'&&$value!==''&&!filter_var($value,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid business email.');if(str_ends_with($key,'_url')&&$value!==''&&!filter_var($value,FILTER_VALIDATE_URL))throw new RuntimeException('Social links must be complete valid URLs.');if(in_array($key,['verified_customers','completed_projects','years_experience'],true)&&$value!==''&&!ctype_digit($value))throw new RuntimeException($label.' must be a whole number or blank.');$stmt->execute([$key,$value]);}$notice='Website settings saved.';}catch(RuntimeException $exception){$error=$exception->getMessage();}}
$adminTitle='Website settings · Yucca Fabrics';require __DIR__.'/../../includes/admin-header.php';
?>
<h1 class="font-serif text-4xl">Website settings</h1><p class="mt-2 text-sm text-gray-600">Keep public contact and payment information current.</p><?php if($notice||$error): ?><p class="mt-4 rounded p-3 text-sm <?= $error?'bg-red-50 text-red-800':'bg-green-50 text-green-800' ?>"><?= e($error?:$notice) ?></p><?php endif; ?><form method="post" class="mt-7 grid max-w-3xl gap-4 bg-white p-6"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><?php foreach($fields as $key=>$label): ?><label class="text-sm"><?= e($label) ?><?php if($key==='bank_details'): ?><textarea class="form-control mt-1" name="<?= e($key) ?>" rows="4"><?= e(setting($key)) ?></textarea><?php else: ?><input class="form-control mt-1" name="<?= e($key) ?>" value="<?= e(setting($key)) ?>" <?= $key==='business_email'?'type="email"':'' ?><?= str_ends_with($key,'_url')?' type="url" placeholder="https://… (blank shows a placeholder link on the site)"':'' ?>><?php endif; ?></label><?php endforeach; ?><div><button class="rounded-full bg-forest px-6 py-3 text-sm font-semibold text-white">Save settings</button></div></form><aside class="mt-6 max-w-3xl border-l-2 border-clay bg-white p-5 text-sm leading-6 text-gray-600">Currency, tax and delivery rates are configured through the server environment (APP_CURRENCY, APP_TAX_RATE and APP_DELIVERY_FEE). M-Pesa credentials must remain server-side and are never edited or displayed here.</aside>
